"""Build a Persian summary from completed, independently audited artifacts."""
from pathlib import Path
import json,sys
root=Path(sys.argv[1]);r=json.loads((root/'results.json').read_text());a=json.loads((root/'audit.json').read_text())
def fa(value):return f'{value:,}'.translate(str.maketrans('0123456789','۰۱۲۳۴۵۶۷۸۹'))
lines=['# گزارش آزمون یک میلیون سناریوی ترکیبی','',f"تعداد اجراشده: **{fa(r['total'])}**؛ موفق در همهٔ کنترل‌ها: **{fa(r['passed'])}**؛ ناموفق: **{fa(r['failed'])}**.",'',f"این مجموعه {fa(r['topicCount'])} موضوع فعلی سامانه را پوشش می‌دهد. هر متن بین یک تا پنج موضوع دارد. همهٔ متن‌ها از مسیر واقعی `localAnalysis → prepareAnalysis → questionsFor` عبور کرده‌اند و فعال‌بودن تأیید اولیه بررسی شده است.",'','| تعداد موضوع در هر روایت | سناریوی اجراشده | موفق | ناموفق | مجموعهٔ موضوعی متفاوت |','| --- | --- | --- | --- | --- |']
for k,row in r['byTopicCount'].items():lines.append(f"| {fa(int(k))} | {fa(row['total'])} | {fa(row['passed'])} | {fa(row['failed'])} | {fa(a['distinctTopicSetsBySize'][k])} |")
lines+=['',f"در مجموع **{fa(a['distinctTopicSets'])} مجموعهٔ موضوعی متفاوت** بررسی شده است. {fa(a['withNegativeControl'])} روایت، عبارت منفی، نامطمئن، فرضی یا مشاهدهٔ عادی هم دارد. {fa(a['withRepeatedOccurrence'])} روایت شامل تکرار یک رخداد در زمانی دیگر است.",'','## کنترل‌های انجام‌شده','',
'- برابری دقیق مجموعهٔ موضوع‌های تشخیص‌داده‌شده با برچسب‌های از پیش تعیین‌شده؛ هم موضوع جاافتاده و هم موضوع اضافه خطا محسوب می‌شود.',
'- وجود شاهد عیناً نقل‌شده از متن برای هر موضوع و اتصال پاسخ‌های پیشنهادی و بخش‌های رخداد به متن.',
'- وجود سؤال‌های جزئیات برای همهٔ موضوع‌های مورد انتظار و تکرارنشدن شناسهٔ سؤال‌ها.',
'- فعال‌بودن مرحلهٔ تأیید کاربر پیش از ادامه.',
'- بازخوانی مستقل تمام فایل‌ها، کنترل تعداد ردیف، CRC، هش فایل‌های فشرده و بازشده و نبود متن تکراری با هش SHA-256.',
f"- زمان اجرای اصلی: {fa(round(r['durationSeconds']))} ثانیه؛ آغاز: `{r['startedAt']}`؛ پایان: `{r['finishedAt']}`.",'','## منشأ و محدودیت نتیجه','',
f"متن‌ها از {fa(r['seedPhraseCount'])} عبارت پایه با برچسب مستقل و ۱۴ عبارت کنترلی ساخته شده‌اند. ترتیب رخدادها، عبارت‌بندی، تکرار، محل عبارت منفی، نشانه‌گذاری، ی/ک فارسی و عربی، زمان و مکان تغییر می‌کند. بخشی از متن‌ها فقط در زمینهٔ زمان یا مکان متفاوت‌اند. این‌ها یک میلیون روایت مستقلِ نوشته‌شده توسط انسان یا بازبینی‌شده توسط کارشناس نیستند.",
'',
'این مجموعه برای آزمون بازگشت خطا و ترکیب‌پذیری است. آزمون اولیه از همین خانوادهٔ تولید سناریو برای یافتن خطا استفاده شد؛ بنابراین نتیجهٔ کامل، ارزیابی مستقلِ تعمیم مدل به گزارش‌های واقعی یا اثبات دقت صددرصدی نیست. کیفیت معنایی همهٔ کادرهای پاسخ، صوت‌به‌متن، عملکرد مدل خارجی، بار هم‌زمان کاربران و وصول رسمی گزارش در این آزمون سنجیده نشده‌اند.',
'',
'هیچ درخواست زنده‌ای به مدل خارجی برای این یک میلیون مورد ارسال نشده و وزن مدل تازه‌ای آموزش ندیده است. تکمیل خروجی ناقص API در آزمون‌های جداگانه با پاسخ ساختگی بررسی شده است: ۱۲۶ عبارت تک‌موضوعی و همهٔ ۳٬۹۰۶ زوج دارای ترتیب. مجموع آزمون‌های Node برابر ۱۰۷ و همگی موفق است.',
'',
'گزارش‌ها و رخدادهای این داده‌ها مصنوعی‌اند. هیچ نام واقعی، پروندهٔ هویتی، عقیدهٔ دینی یا وابستگی سیاسی در آن‌ها تولید نشده است. موضوع‌ها پیشنهاد اولیه برای ثبت مشاهده‌اند و احراز جرم محسوب نمی‌شوند.',
'',
'## اصلاح‌های حاصل از بررسی','',
'- جلوگیری از ارتباط اشتباه کلمات دو جملهٔ مستقل؛ مثلاً «سرقت» و «سلاح» در دو رخداد جدا به‌عنوان سرقت مسلحانه ترکیب نمی‌شوند.',
'- محدودکردن اثر نفی و عدم قطعیت به جملهٔ مربوط؛ رخداد مثبتِ جملهٔ دیگر حذف نمی‌شود.',
'- حذف عنوان عمومی تکراری فقط در همان رخدادِ دارای موضوع مشخص؛ رخداد مستقل دیگر حفظ می‌شود.',
'- تکمیل پیشنهادهای تازهٔ API برای همهٔ ۶۳ موضوع فعلی با شاهد متنی، با حفظ اصلاح دستی، پیش‌نویس تأییدشده و پاسخ رد درخواست.',
'',
'## فایل‌ها','',
'هر فایل JSONL فشرده، متن ورودی، موضوع‌های مورد انتظار و تشخیص‌داده‌شده، شاهدها، شناسهٔ سؤال‌ها، عبارت‌های پایه و نتیجهٔ کنترل‌ها را دارد. برچسب مورد انتظار از خروجی سامانه ساخته نشده است.']
for shard in r['shards']:lines+=['',f"- [{shard['file']}](sandbox:{root/shard['file']}) — {fa(shard['records'])} ردیف، حدود {fa(round(shard['gzipBytes']/1048576))} مگابایت."]
lines+=['',f"[results.json](sandbox:{root/'results.json'}) · [audit.json](sandbox:{root/'audit.json'})",'',
'برای بازتولید از کد پروژه:','',
'```sh\nnode evaluation/run-million.mjs --count 1000000 --out /absolute/output/path\npython evaluation/audit-corpus.py /absolute/output/path\n```','']
(root/'ravi-million-report.fa.md').write_text('\n'.join(lines))
